// HasSLADefinition applies the HasEdge predicate on the "sla_definition" edge.
func HasSLADefinition() predicate.SLAState {
	return predicate.SLAState(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SLADefinitionTable, SLADefinitionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSLADefinitionWith applies the HasEdge predicate on the "sla_definition" edge with a given conditions (other predicates).
func HasSLADefinitionWith(preds ...predicate.SLADefinition) predicate.SLAState {
	return predicate.SLAState(func(s *sql.Selector) {
		step := newSLADefinitionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SLAState) predicate.SLAState {
	return predicate.SLAState(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SLAState) predicate.SLAState {
	return predicate.SLAState(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SLAState) predicate.SLAState {
	return predicate.SLAState(sql.NotPredicates(p))
}
